using System; using System.Linq; using Microsoft.EntityFrameworkCore; using DCMS.Infrastructure.Data; using DCMS.Domain.Entities; class Program { static void Main() { var options = new DbContextOptionsBuilder<ApplicationDbContext>().UseNpgsql("Host=localhost;Database=dcms;Username=postgres;Password=postgres").Options; using var db = new ApplicationDbContext(options); try { var notes = db.DoctorNotes.ToList(); Console.WriteLine("Count: " + notes.Count); } catch (Exception ex) { Console.WriteLine("EXCEPTION: " + ex.ToString()); } } }
